import base64,json,sys
from dataclasses import asdict
sys.path.insert(0,sys.argv[1])
from loader import read_package
from diagnostics import ReadFailure
def capture(s):
 return {"path":s.path,"role":s.role,"raw_base64":base64.b64encode(s.raw).decode("ascii"),"sha256":s.sha256,"complete":s.complete,"valid_utf8":s.valid_utf8,"text":s.text}
try:
 r=read_package(sys.argv[2]); print(json.dumps({"status":r.status,"validation_status":r.validation_status,"selection_mode":r.selection_mode,"source_paths":r.source_paths,"items":[{"data":i.value,"location":asdict(i.location)} for i in r.items],"sources":[capture(s) for s in r.sources]},ensure_ascii=False)); sys.exit(0)
except ReadFailure as e:
 print(json.dumps({"status":"ERROR","diagnostic":asdict(e.diagnostic),"sources":[capture(s) for s in e.sources]},ensure_ascii=False)); sys.exit(2)

